def test_send_input_fills_defaults() -> None:
    client, exporter = make_client()
    client.send(LogInput("hello", attributes={"n": 1}, trace_id="AB" * 16, span_id="CD" * 8))
    client.flush(5)
    (record,) = exporter.records
    assert record.body == "hello"
    assert record.severity is Severity.INFO
    assert dict(record.resource) == {"service.name": "svc"}
    assert dict(record.attributes) == {"n": 1}
    assert record.trace_id == "ab" * 16
    assert record.span_id == "cd" * 8
    assert record.timestamp.tzinfo is not None
    client.close()


def test_send_record_merges_resource() -> None:
    client, exporter = make_client()
    client.send(LogRecord("a", timestamp=TS, resource={"host.name": "h", "service.name": "x"}))
    client.send(LogRecord("b", timestamp=TS))
    client.flush(5)
    first, second = exporter.records
    assert dict(first.resource) == {"service.name": "x", "host.name": "h"}
    assert dict(second.resource) == {"service.name": "svc"}
    assert first.timestamp == TS
    client.close()


def test_trace_correlation_from_active_span() -> None:
    client, exporter = make_client()
    assert current_trace_context() is None
    with tracer.start_as_current_span("op") as span:
        context = span.get_span_context()
        client.send(LogInput("inside"))
        client.send(LogInput("explicit", trace_id="12" * 16))
        assert current_trace_context() == (
            format(context.trace_id, "032x"),
            format(context.span_id, "016x"),
            int(context.trace_flags),
        )
    client.send(LogInput("outside"))
    client.flush(5)
    inside, explicit, outside = exporter.records
    assert inside.trace_id == format(context.trace_id, "032x")
    assert inside.span_id == format(context.span_id, "016x")
    assert inside.trace_flags == int(context.trace_flags)
    assert explicit.trace_id == "12" * 16
    assert explicit.span_id is None
    assert outside.trace_id is None
    client.close()


