def test_send_batch_stats_and_context_manager() -> None:
    exporter = InMemoryLogExporter()
    with BatchingLogClient(exporter) as client:
        client.send_batch([LogInput(f"m{i}") for i in range(3)])
        client.flush(5)
        assert client.stats().sent == 3
    assert exporter.shutdown_calls == 1
    client.close()  # idempotent
    client.send(LogInput("late"))
    assert client.stats().dropped == 1


def test_logger_facade() -> None:
    client, exporter = make_client()
    log = client.logger("app", {"component": "api"}, min_severity=Severity.DEBUG)
    assert log.is_enabled(Severity.DEBUG)
    assert not log.is_enabled(Severity.TRACE)
    log.trace("dropped")
    log.debug("d")
    log.info("i", {"n": 1})
    log.warn("w")
    log.warning("w2")
    log.error("e")
    log.fatal("f")
    child = log.child({"request": "r1"})
    child.info("from child", {"component": "override"})
    client.flush(5)
    records = exporter.records
    assert [r.body for r in records] == ["d", "i", "w", "w2", "e", "f", "from child"]
    assert [r.severity for r in records][:6] == [
        Severity.DEBUG,
        Severity.INFO,
        Severity.WARN,
        Severity.WARN,
        Severity.ERROR,
        Severity.FATAL,
    ]
    assert dict(records[1].attributes) == {"component": "api", "logger.name": "app", "n": 1}
    assert dict(records[-1].attributes) == {
        "component": "override",
        "logger.name": "app",
        "request": "r1",
    }
    default = client.logger()
    default.debug("hidden")
    default.info("shown")
    client.flush(5)
    assert exporter.records[-1].body == "shown"
    assert "logger.name" not in exporter.records[-1].attributes
    client.close()


def test_redaction_processor() -> None:
    processor = RedactionProcessor(patterns=[r"\d{4}-\d{4}", re.compile("secret-[a-z]+")])
    record = LogRecord(
        "card 1234-5678 and secret-abc",
        attributes={
            "Authorization": "Bearer x",
            "nested": {"api_key": "k", "list": ["1111-2222", {"token": "t"}], "ok": 1},
            "tuple": ("secret-xyz",),
            "wrapped": Secret("s3cr3t"),
            "flag": True,
        },
    )
    out = processor.process(record)
    assert out.body == "card [REDACTED] and [REDACTED]"
    assert dict(out.attributes) == {
        "Authorization": "[REDACTED]",
        "nested": {
            "api_key": "[REDACTED]",
            "list": ["[REDACTED]", {"token": "[REDACTED]"}],
            "ok": 1,
        },
        "tuple": ["[REDACTED]"],
        "wrapped": "[REDACTED]",
        "flag": True,
    }
    assert record.body.startswith("card 1234")  # input untouched
    custom = RedactionProcessor(keys=["user", ""], replacement="***")
    assert custom.is_sensitive("UserName")
    assert not custom.is_sensitive("password")
    assert custom.redact_attributes({"user": "bob"}) == {"user": "***"}
    assert "password" in DEFAULT_REDACT_KEYS


